/// <summary>
/// Contract for DataUtilitas process
/// </summary>
[DataContractAttribute, SysOperationContractProcessing(classStr(NDXUtilitasUIBuilder))]
internal final class NDXUtilitasDataOpContract
{
    NDXUtilitasDataOpServiceController utilitasDataOpServiceController;
    Dialog dialog;

    NoYes allItems;
    ItemId itemId;

    str companies;

}

Method.Source:
[DataMemberAttribute("itemId"), SysOperationLabelAttribute("@NDX:NDXSelectedItem")]
public itemId parmItemId(itemId _itemId = itemId)
{
    itemId = _itemId;
    return itemId;
}

[DataMemberAttribute("allItems"), SysOperationLabelAttribute("@NDX:NDXTransferAllItems"), SysOperationHelpText("@NDX:NDXTransferAllItems_Help"),  SysOperationDisplayOrder('1')]
public NoYes parmAllCatalogItems(NoYes _allItems = allItems)
{
    allItems = _allItems;
    return allItems;
}

[DataMemberAttribute("companies"), SysOperationLabelAttribute("@NDX:NDXUtilitasSelectedCompanies"), SysOperationHelpText("@NDX:NDXUtilitasSelectedCompanies_Help")]
public str parmCompanies(str _companies = companies)
{
    companies = _companies;
    return companies;
}

/// <summary>
/// init method
/// </summary>
public void initialize()
{
    allItems = false;
    companies = curExt();
}
